insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('geomech', 'beginner', 'module', 'm01-what-a-mechanical-earth-model-is', 1, 'What is a mechanical earth model, at its simplest?', '["A three-dimensional finite element model.", "Six numbers at every depth: three stresses, a pore pressure, a sonic reading and a strength.", "A calibrated relationship between drilling parameters and formation properties, built from offset well data across a field.", "A description of the elastic properties of every formation, obtained from core measurements at regular intervals along the well."]'::jsonb, 1, 'There is no seventh input, and everything the rest of the course computes is a function of those six.'),
  ('geomech', 'beginner', 'module', 'm01-what-a-mechanical-earth-model-is', 2, 'Which two of the six are not measured on a normal well?', '["The pore pressure and the strength.", "The overburden and the sonic slowness, both of which require a logging run that is often skipped in the shallow section.", "The strength and the friction angle, neither of which can be obtained without a triaxial test programme on core.", "The two horizontal stresses."]'::jsonb, 3, 'Shmin is bounded at a handful of depths by a leak-off test and SHmax is essentially never measured directly at all.'),
  ('geomech', 'beginner', 'module', 'm01-what-a-mechanical-earth-model-is', 3, 'Where does the overburden come from?', '["An integral of a bulk density log from surface, which is arithmetic on a measurement rather than a model.", "A correlation with the pore pressure.", "The average of the two horizontal stresses, scaled by a factor that depends on the faulting regime in the field.", "A leak-off test performed at each casing shoe, extrapolated between shoes using a compaction relationship."]'::jsonb, 0, 'The main uncertainty is the shallow section, where no density log was run.'),
  ('geomech', 'beginner', 'module', 'm01-what-a-mechanical-earth-model-is', 4, 'How is a pressure converted into an equivalent mud weight?', '["Divide by the overburden gradient.", "Multiply by the ratio of the mud density to the density of water, then divide by the measured depth along the hole.", "Divide by gravity and by the true vertical depth.", "Subtract the pore pressure and divide the remainder by the true vertical depth at the point of interest."]'::jsonb, 2, 'It needs a depth. A mud weight quoted without one cannot be converted back into a pressure.'),
  ('geomech', 'beginner', 'module', 'm01-what-a-mechanical-earth-model-is', 5, 'Why is equivalent mud weight the working unit?', '["Because it is dimensionless and therefore easier to compare.", "Because the answer is a mud weight, and the driller orders mud by density.", "Because the failure criteria are expressed in terms of density rather than pressure, so no conversion is needed at the end.", "Because equivalent mud weight does not depend on depth, which makes it the only unit that can be compared between wells."]'::jsonb, 1, 'A window quoted as a density range is directly actionable. The same window in pascals needs a conversion first.'),
  ('geomech', 'beginner', 'module', 'm01-what-a-mechanical-earth-model-is', 6, 'Why is pressure the calculating unit?', '["Because the physics is in pressures, and dividing by depth partway through only adds a place to make a mistake.", "Because pascals are the SI unit.", "Because the engine''s numerical routines are unstable when working with densities rather than absolute pressures.", "Because equivalent mud weight cannot represent a negative value, which the effective stresses sometimes require."]'::jsonb, 0, 'The engine works in pascals throughout and converts once at the end.'),
  ('geomech', 'beginner', 'module', 'm01-what-a-mechanical-earth-model-is', 7, 'What is the first decision this model is for?', '["Where to place the surface location.", "Which formations to core and log, and at what interval, so that the model can be calibrated for the next well in the field.", "How fast the section can be drilled without exceeding the equivalent circulating density limit at the casing shoe.", "What mud weight to put in the hole at each depth."]'::jsonb, 3, 'The lower bound, the upper bound, and where between them to sit.'),
  ('geomech', 'beginner', 'module', 'm01-what-a-mechanical-earth-model-is', 8, 'What is the second decision, and why is it often more valuable?', '["The casing programme, because it fixes the shoe depths.", "The mud system, because the chemistry of the mud determines whether a reactive shale section can be drilled at all.", "The trajectory, because the window depends strongly on which way the hole points.", "The bit selection, because the rock strength determined here also sets the expected rate of penetration for the section."]'::jsonb, 2, 'Turning a hole from vertical to horizontal along the maximum horizontal stress can cost a quarter of the window with no rock property changing.'),
  ('geomech', 'beginner', 'module', 'm01-what-a-mechanical-earth-model-is', 9, 'What is the third decision?', '["How many casing strings to run in total.", "Where to set casing, which this course approaches from the open hole side.", "Whether the well can be drilled at all, which depends on whether any section has a window narrower than the operational tolerance.", "What cement slurry density to use, which must sit inside the same window as the drilling mud does."]'::jsonb, 1, 'Well control asks whether the shoe can hold a kick. This course asks whether the open hole can stand the mud.'),
  ('geomech', 'beginner', 'module', 'm01-what-a-mechanical-earth-model-is', 10, 'Which of these is this model NOT for?', '["Designing a hydraulic fracture treatment, which is about propagating a fracture into the far field.", "Choosing a mud weight for a hole section.", "Comparing two candidate trajectories to the same target on the basis of how much mud weight window each would have.", "Providing the fracture gradient that a well control kick tolerance calculation compares its casing pressures against."]'::jsonb, 0, 'Fracture initiation here is a wellbore stability limit, and propagation is a different calculation entirely.'),
  ('geomech', 'beginner', 'module', 'm01-what-a-mechanical-earth-model-is', 11, 'What is NOT on the list of six inputs?', '["The friction angle.", "The pore pressure, which arrives from the pore pressure course rather than being computed inside the geomechanics module.", "The unconfined compressive strength, which is derived from the sonic reading rather than being an input in its own right.", "Temperature, time, chemistry, anisotropy, natural fractures and bedding."]'::jsonb, 3, 'All six of those affect stability in the field, and the Expert tier names each one and says what adding it would take.'),
  ('geomech', 'beginner', 'module', 'm01-what-a-mechanical-earth-model-is', 12, 'Why does the uncertainty in the horizontal stresses matter so much?', '["Because they are the largest stresses in the model.", "Because the window is a difference of two large numbers, so a small relative error in each is a large one in the width.", "Because the horizontal stresses are the only inputs that appear in both of the two failure criteria used by the engine.", "Because an error in them propagates into the pore pressure estimate, which then feeds back into the stress model again."]'::jsonb, 1, 'Both bounds are tens of megapascals and the window between them is often a few, so ten percent on a stress is a large fraction of the window.'),
  ('geomech', 'beginner', 'module', 'm01-what-a-mechanical-earth-model-is', 13, 'What is the calibration loop?', '["Running the model twice with different seeds.", "Comparing the computed stresses against a second independent implementation of the same equations, then reconciling any differences.", "Drill a section, watch what the hole does, adjust the model to have predicted it, use it for the next section.", "Measuring the mud weight actually used against the planned mud weight and correcting the model by the ratio of the two."]'::jsonb, 2, 'It is why the first section of a well is drilled most conservatively, and it is how field geomechanics is actually practised.'),
  ('geomech', 'beginner', 'module', 'm01-what-a-mechanical-earth-model-is', 14, 'What does the deliverable look like?', '["One chart per well: measured depth against equivalent mud weight, with a lower bound, an upper bound and the plan between them.", "A table of elastic properties per formation.", "A three-dimensional visualisation of the stress field around the wellbore at each of the critical depths in the section.", "A single recommended mud weight for the well, chosen so that it satisfies every depth simultaneously with a safety factor."]'::jsonb, 0, 'Three groups read it: the mud programme, the well planner and the casing designer, and all three want the same chart.'),
  ('geomech', 'beginner', 'module', 'm01-what-a-mechanical-earth-model-is', 15, 'At a depth where the overburden is the largest of the three stresses, what regime is that?', '["Strike-slip faulting, by definition of the ordering.", "Reverse faulting, because a vertical stress larger than both horizontal ones drives thrusting on favourably oriented planes.", "It cannot be determined without knowing which of the two horizontal stresses is larger than the other one.", "Normal faulting."]'::jsonb, 3, 'The regime is defined by where the overburden sits in the ordering of the three principal stresses.'),
  ('geomech', 'beginner', 'module', 'm02-the-overburden-and-the-pore-pressure', 1, 'The overburden at a depth is what, physically?', '["The weight per unit area of everything above it, including the fluid in the pore space.", "The stress that the rock can carry.", "The pressure exerted by a column of mud of the same height, which is why it is quoted as an equivalent mud weight.", "The difference between the total vertical stress and the pore pressure at the depth in question."]'::jsonb, 0, 'It is the one principal stress with a direct physical meaning that requires no model at all.'),
  ('geomech', 'beginner', 'module', 'm02-the-overburden-and-the-pore-pressure', 2, 'Why is the shallow part of the overburden integral uncertain?', '["Because the density tool does not work at low pressure.", "Because the shallow sediment has not compacted, so its density changes too fast for a logging tool to resolve accurately.", "Because the surface and conductor sections are rarely logged for density.", "Because seawater above the mudline has to be included, and its density varies with temperature and salinity down the column."]'::jsonb, 2, 'That gap gets filled from a regional trend or an assumed compaction curve.'),
  ('geomech', 'beginner', 'module', 'm02-the-overburden-and-the-pore-pressure', 3, 'This profile carries a constant overburden gradient. What does that assume?', '["That the rock has no porosity at all.", "That the average bulk density above every depth is the same, which is only true well below surface.", "That the density log was run over the whole interval and returned a constant value throughout the sedimentary sequence.", "That the pore fluid density equals the grain density, so the bulk density does not depend on the porosity at any depth."]'::jsonb, 1, 'A real gradient starts near the density of water at the mudline and climbs as the sediment compacts.'),
  ('geomech', 'beginner', 'module', 'm02-the-overburden-and-the-pore-pressure', 4, 'Where does the constant gradient assumption cost most?', '["At total depth, where the errors accumulate.", "In the middle of the section, where a real gradient is steepest and the constant value crosses it at some point.", "It costs nothing anywhere, because the overburden is only ever used as a difference between two depths.", "At the top of the hole."]'::jsonb, 3, 'By the time the integral has 2000 m of compacted rock in it, the top 100 m barely moves the answer.'),
  ('geomech', 'beginner', 'module', 'm02-the-overburden-and-the-pore-pressure', 5, 'Why does an overburden error at shallow depth matter here specifically?', '["Because the horizontal stresses are computed FROM the overburden, so the error propagates into them.", "Because the sonic log is also unreliable there.", "Because the pore pressure model uses the overburden as its reference, so an error in one is duplicated in the other.", "Because the shallowest section is where the casing shoe is set, and the shoe fracture gradient depends on it directly."]'::jsonb, 0, 'An overburden that is too large at shallow depth gives horizontal stresses that are too large there.'),
  ('geomech', 'beginner', 'module', 'm02-the-overburden-and-the-pore-pressure', 6, 'Where does the pore pressure in this model come from?', '["From the overburden and a Poisson ratio.", "From the sonic log using the same correlation family that produces the unconfined compressive strength column.", "From upstream. The engine deliberately does not compute it.", "From a leak-off test at the casing shoe, extrapolated to the rest of the section by a linear trend with depth."]'::jsonb, 2, 'That boundary is deliberate: a module that both estimates pore pressure and consumes it can hide a circular argument.'),
  ('geomech', 'beginner', 'module', 'm02-the-overburden-and-the-pore-pressure', 7, 'What shape does this profile''s pore pressure have?', '["A single step at the reservoir top.", "Hydrostatic to 1500 m, then a ramp that climbs steadily below it.", "A steady climb from the mudline that accelerates with depth, following the compaction of the sediment column above it.", "Constant in pressure rather than in gradient, which is what a sealed and fully overpressured section produces."]'::jsonb, 1, 'A normally pressured section over a mildly overpressured one, which is the classic setting.'),
  ('geomech', 'beginner', 'module', 'm02-the-overburden-and-the-pore-pressure', 8, 'What does a hydrostatic pore pressure gradient mean?', '["The fluid escaped upward as fast as the sediment compacted, so the pressure is just the weight of the water above.", "The formation contains no mobile fluid.", "The rock is impermeable, so the fluid pressure equals the pressure that was present when the sediment was first deposited.", "The pore pressure equals the overburden, so the grain framework carries none of the load at that depth."]'::jsonb, 0, 'It is the default state of a normally pressured, well drained sedimentary section.'),
  ('geomech', 'beginner', 'module', 'm02-the-overburden-and-the-pore-pressure', 9, 'Below 1500 m the gradient starts climbing. Account for it.', '["The formation temperature is rising.", "The rock has become more permeable with depth, allowing pressure to communicate upward from a deeper source.", "The overburden gradient has increased, so the total stress and the pore pressure have both risen in proportion.", "The escape stopped working, so the fluid is carrying part of the load the grains would otherwise carry."]'::jsonb, 3, 'Usually a seal: a shale that dewatered too slowly for the pressure to equalise as the section compacted.'),
  ('geomech', 'beginner', 'module', 'm02-the-overburden-and-the-pore-pressure', 10, 'What happens to the effective vertical stress across the ramp?', '["It grows faster, because both terms are rising.", "It becomes negative, which is why an overpressured section cannot support a wellbore without additional mud weight.", "It stops growing as fast, because the pore pressure is eating the increase.", "It stays exactly constant, because the ramp is defined as the condition under which the two terms cancel."]'::jsonb, 2, 'Deeper rock in an overpressured section can be geomechanically weaker than shallower rock above it.'),
  ('geomech', 'beginner', 'module', 'm02-the-overburden-and-the-pore-pressure', 11, 'State the effective stress relationship.', '["Total stress divided by the pore pressure.", "Total stress less the Biot coefficient times the pore pressure.", "The difference between the largest and the smallest of the three principal total stresses at the point in question.", "The total stress less the hydrostatic pressure, regardless of what the actual pore pressure at that depth turns out to be."]'::jsonb, 1, 'It is the stress carried by the grain framework, and it is what controls deformation and failure.'),
  ('geomech', 'beginner', 'module', 'm02-the-overburden-and-the-pore-pressure', 12, 'Why does the pore pressure cancel out of failure behaviour?', '["Because uniform pressure from every side compresses a grain without distorting it, and distortion is what breaks rock.", "Because it is much smaller than the stresses.", "Because the failure criteria are written in terms of stress differences, and the pore pressure appears in only one of them.", "Because the pore fluid is incompressible, so it transmits no shear and therefore has no effect on the grain framework."]'::jsonb, 0, 'The pore pressure subtracts equally from every direction, so it drops out of the differences that matter.'),
  ('geomech', 'beginner', 'module', 'm02-the-overburden-and-the-pore-pressure', 13, 'What is the Biot coefficient?', '["The ratio of horizontal to vertical stress.", "The proportion of the pore space that is connected, and therefore able to transmit pressure through the rock framework.", "The fraction of the overburden carried by the fluid rather than by the grains, which is the definition of overpressure.", "A correction for the fact that a rock is not a bag of incompressible grains."]'::jsonb, 3, 'It runs between zero and one, closer to one for a soft high-porosity rock, and setting it to one is the conservative default.'),
  ('geomech', 'beginner', 'module', 'm02-the-overburden-and-the-pore-pressure', 14, 'What sign convention does this course use?', '["Tension positive, as in structural engineering.", "Compression positive for the total stresses and tension positive for the effective ones, which is why the two must not be mixed.", "Compression positive, which is standard in rock mechanics.", "It varies by quantity, with the stresses compression-positive and the pore pressure entering with the opposite sign."]'::jsonb, 2, 'So a negative effective stress means tension, which is exactly what the fracture initiation criterion is looking for.'),
  ('geomech', 'beginner', 'module', 'm02-the-overburden-and-the-pore-pressure', 15, 'What is the honest position on the pore pressure input?', '["It is the best constrained of the six inputs.", "If it is wrong, everything here is wrong, and this course cannot tell you whether it is.", "It matters only for the lower bound, so an error in it leaves the fracture gradient and the upper bound unaffected.", "It can be checked against the stress model, because a pore pressure above the minimum horizontal stress is impossible."]'::jsonb, 1, 'That is why a geomechanics study and a pore pressure study are done together and calibrated against the same well events.'),
  ('geomech', 'beginner', 'module', 'm03-the-horizontal-stresses', 1, 'What picture does the uniaxial estimate rest on?', '["Rock free to deform in every direction.", "A block of rock loaded from the side by tectonic forces, with the overburden playing no part in the horizontal stress at all.", "Rock buried under more rock, free to compress vertically and confined horizontally.", "A rock mass that has already failed on existing faults, so the stress state sits exactly on the frictional limit everywhere."]'::jsonb, 2, 'That is a reasonable picture for a thick flat-lying sequence loaded by burial, and a poor one near a fault or a salt body.'),
  ('geomech', 'beginner', 'module', 'm03-the-horizontal-stresses', 2, 'Write the three parts of the horizontal stress estimate.', '["k0 times the effective vertical stress, plus the pore pressure back, plus a tectonic strain term.", "The overburden times a constant.", "The effective vertical stress divided by the frictional limit ratio, plus a correction for the faulting regime in force.", "A weighted average of the overburden and the pore pressure, with the weights set by the Poisson ratio of the formation."]'::jsonb, 0, 'Burial, then a conversion back from effective to total, then the regional deformation.'),
  ('geomech', 'beginner', 'module', 'm03-the-horizontal-stresses', 3, 'What is k0, in terms of the Poisson ratio?', '["One minus nu, divided by nu.", "nu divided by one minus nu.", "The ratio of the Young''s modulus to the shear modulus, which reduces to a function of the Poisson ratio alone.", "Twice nu divided by one plus nu, which is the plane strain form of the same elastic relationship."]'::jsonb, 1, 'Two lines from Hooke''s law under uniaxial strain, and no rock physics beyond it.'),
  ('geomech', 'beginner', 'module', 'm03-the-horizontal-stresses', 4, 'Why is k0 always below one?', '["Because the Poisson ratio is always below one.", "Because the frictional limits clamp it there, and a value above one would require a reverse faulting stress state.", "Because the horizontal stresses are measured and always come out smaller than the overburden in a sedimentary basin.", "Because a rock loaded from above by burial alone carries less horizontal effective stress than vertical."]'::jsonb, 3, 'It approaches one as the Poisson ratio approaches 0.5, which is an incompressible material such as salt.'),
  ('geomech', 'beginner', 'module', 'm03-the-horizontal-stresses', 5, 'Where is k0 most sensitive to an error in the Poisson ratio?', '["At high Poisson ratio, because the relationship accelerates as nu rises toward a half.", "At low Poisson ratio.", "It is equally sensitive everywhere, because the relationship between the two is linear over the range of interest.", "It is insensitive throughout, because the frictional bounds clamp the result before the difference has any effect."]'::jsonb, 0, 'So a Poisson ratio uncertainty matters more in shale, where nu is high, than in sandstone, where it is low.'),
  ('geomech', 'beginner', 'module', 'm03-the-horizontal-stresses', 6, 'What does the tectonic strain term represent?', '["The strain caused by drilling the hole.", "The elastic response of the rock to the removal of overburden by erosion, which reduces the horizontal stress over geological time.", "Regional deformation that is not burial: plate motion stretching or squeezing the whole section.", "The difference between the plane strain and plane stress solutions, applied as a correction to the burial term."]'::jsonb, 2, 'It is added on top of what the overburden alone would produce.'),
  ('geomech', 'beginner', 'module', 'm03-the-horizontal-stresses', 7, 'What is the critical property of the tectonic strain term?', '["It is proportional to the overburden.", "It does not depend on depth. The same pressure is added at every level.", "It scales with the effective vertical stress, so it grows in exactly the same proportion as the burial term does with depth.", "It is zero above the depth at which the section began to deform, and constant below it, giving a step in the profile."]'::jsonb, 1, 'That is what makes it dominate at shallow depth, where the burial term is small.'),
  ('geomech', 'beginner', 'module', 'm03-the-horizontal-stresses', 8, 'Shmin and SHmax come from one formula. What differs?', '["The order of the two tectonic strains, so the entire difference between them is tectonic.", "The Poisson ratio used in each.", "The frictional limit applied to each, since the active limit bounds one of them and the passive limit bounds the other.", "The effective vertical stress, which is computed with the Biot coefficient for one and without it for the other."]'::jsonb, 0, 'Burial alone cannot distinguish one horizontal direction from another, because burial has no horizontal direction.'),
  ('geomech', 'beginner', 'module', 'm03-the-horizontal-stresses', 9, 'In this profile, what is true of the difference between SHmax and Shmin?', '["It grows in proportion to the depth.", "It falls with depth, which is why the two stress curves converge toward each other at the bottom of the profile.", "It varies with lithology, being largest in the stiff beds and smallest in the soft ones throughout the section.", "It is the same pressure at every depth."]'::jsonb, 3, 'A constant strain difference gives a constant stress difference, which is a property of the model rather than of the earth.'),
  ('geomech', 'beginner', 'module', 'm03-the-horizontal-stresses', 10, 'Why does the gap between the two horizontal stresses LOOK like it closes with depth?', '["Because the two stresses really do converge.", "Because the frictional bounds narrow with depth, squeezing the two estimates toward each other as the section gets deeper.", "Because an equivalent mud weight divides by a depth that is growing.", "Because the strain terms decay with depth as the elastic modulus of the rock increases through compaction."]'::jsonb, 2, 'The pressure difference is fixed. A gradient plot compresses differences at depth and exaggerates them at the top.'),
  ('geomech', 'beginner', 'module', 'm03-the-horizontal-stresses', 11, 'What are the frictional bounds?', '["Bounds on the rate of change of stress with depth.", "Limits on the ratio between the largest and smallest effective principal stresses, set by friction on existing faults.", "The maximum and minimum values the horizontal stresses have taken over the geological history of the basin in question.", "Constraints derived from leak-off tests, which bound the minimum horizontal stress from above at each casing shoe."]'::jsonb, 1, 'A stress state that would cause slip on a favourably oriented existing fault cannot persist, because the fault slips.'),
  ('geomech', 'beginner', 'module', 'm03-the-horizontal-stresses', 12, 'What is the ratio q, and what is it at a friction angle of 30 degrees?', '["One plus the sine of the friction angle over one minus it, which is exactly three at 30 degrees.", "The tangent of the friction angle, which is about 0.577.", "The reciprocal of the sine of the friction angle, which gives two at 30 degrees and falls as the angle rises further.", "The friction angle in radians divided by a quarter of pi, which normalises it to one at 45 degrees of friction."]'::jsonb, 0, 'That is the Mohr-Coulomb slip condition for a cohesionless surface, and the value of three is the one most often quoted.'),
  ('geomech', 'beginner', 'module', 'm03-the-horizontal-stresses', 13, 'How does a bound differ from an estimate?', '["A bound is more accurate than an estimate.", "An estimate carries an uncertainty range and a bound does not, which is why bounds are preferred wherever they are available.", "A bound is derived from measurements and an estimate from a model, so the two have different provenance but the same status.", "An estimate says where the value probably is. A bound says what it cannot be."]'::jsonb, 3, 'The engine''s own header notes that a legacy version mixed the two, which is claiming to know a stress when you only know a range.'),
  ('geomech', 'beginner', 'module', 'm03-the-horizontal-stresses', 14, 'What does the engine do when the estimate exceeds a bound?', '["Raises an error and refuses to run.", "Substitutes the bound for the estimate silently, since the bound is the more defensible of the two statements available.", "Clamps it to the bound and counts the clamp.", "Reduces the tectonic strain until the estimate falls inside the bound, then reports the adjusted strain in its warnings."]'::jsonb, 2, 'The count is the honest part: a run with many clamps is one whose estimate is being overruled by its own sanity check.'),
  ('geomech', 'beginner', 'module', 'm03-the-horizontal-stresses', 15, 'What is the signature of a clamped answer?', '["A stress larger than the overburden.", "Two stresses coming out exactly equal, or one sitting exactly on a computed bound.", "A negative effective stress, which is the only outcome the frictional bounds are designed to prevent from occurring.", "A large difference between the two horizontal stresses, since clamping always pushes them apart rather than together."]'::jsonb, 1, 'Two stresses agreeing exactly is almost never physical, and at the top of this profile both are clamped to the same value.'),
  ('geomech', 'beginner', 'module', 'm04-strength-from-a-log', 1, 'Define unconfined compressive strength.', '["The load a rock carries at depth.", "The axial load per unit area at which a cylinder of rock fails with nothing holding its sides in.", "The stress difference between the largest and smallest principal stresses at the moment of failure in a triaxial test.", "The pressure at which a rock begins to deform permanently rather than elastically under a hydrostatic load."]'::jsonb, 1, 'The word unconfined is the whole qualification: confine the same plug and it carries far more.'),
  ('geomech', 'beginner', 'module', 'm04-strength-from-a-log', 2, 'Where does UCS appear in the failure criterion?', '["As the intercept: the largest effective stress the rock carries when the confinement is zero.", "As the slope of the failure line.", "As a multiplier on the confining stress, so that a stronger rock gains more from every unit of confinement applied to it.", "As a threshold below which the criterion is not evaluated at all, since a weak rock is assumed to have failed already."]'::jsonb, 0, 'Set the confinement to zero and the largest stress it can carry is exactly UCS, which is the definition restated.'),
  ('geomech', 'beginner', 'module', 'm04-strength-from-a-log', 3, 'What sets the slope of the failure line?', '["The unconfined compressive strength.", "The Poisson ratio, which relates the lateral strain to the axial one and therefore controls the confining response.", "The Biot coefficient, which determines how much of the confining pressure is felt by the grain framework.", "The friction angle, through q."]'::jsonb, 3, 'UCS is the intercept and q is the slope. A rock can be strong in one and weak in the other.'),
  ('geomech', 'beginner', 'module', 'm04-strength-from-a-log', 4, 'State the Horsrud correlation.', '["UCS equals 1200 times an exponential of the slowness.", "UCS equals the product of the bulk density and the square of the compressional velocity, divided by a lithology constant.", "UCS in megapascals equals 0.77 times the compressional velocity in km per second, raised to the power 3.2.", "UCS in megapascals equals 0.77 times the slowness in microseconds per metre, raised to the power of minus 3.2."]'::jsonb, 2, 'Horsrud 2001, calibrated on North Sea shales, and a power law in velocity.'),
  ('geomech', 'beginner', 'module', 'm04-strength-from-a-log', 5, 'State the McNally correlation, and note its unit trap.', '["1200 times the exponential of minus 0.036 times the slowness, with the slowness in microseconds per FOOT.", "1200 times the velocity cubed, in metric units.", "1200 divided by the slowness in microseconds per metre, which is why it reads higher than Horsrud at slow readings.", "1200 times the exponential of the slowness in microseconds per metre, with no conversion needed at the interface."]'::jsonb, 0, 'The engine takes microseconds per metre and converts internally. Putting the wrong unit in changes the answer by orders of magnitude.'),
  ('geomech', 'beginner', 'module', 'm04-strength-from-a-log', 6, 'How many times do the two correlations cross?', '["Never. One is always above the other.", "Twice, and both crossings fall inside this profile''s sonic range.", "Once, at a slowness that depends on the lithology and therefore has to be established separately for each formation.", "Three times, because the power law overtakes the exponential and then falls behind it twice over the full range."]'::jsonb, 1, 'A power law and an exponential can meet at most twice, and here they do.'),
  ('geomech', 'beginner', 'module', 'm04-strength-from-a-log', 7, 'Which correlation reads higher at the SLOWEST readings in this profile?', '["McNally, the sandstone correlation.", "They are within one percent of each other there, which is why the choice makes no practical difference at shallow depth.", "Neither, because both return a null value at slowness values above the range they were calibrated over.", "Horsrud, the shale correlation."]'::jsonb, 3, 'At the shallowest reading Horsrud gives about 39 percent more strength than McNally, from two equally published correlations.'),
  ('geomech', 'beginner', 'module', 'm04-strength-from-a-log', 8, 'What does the double crossing destroy?', '["The usefulness of both correlations.", "The ability to compute a strength at all without knowing the lithology, since the two answers bracket a factor of two.", "Any claim that one correlation is the conservative choice.", "The validity of the Mohr-Coulomb criterion, which assumes a single well-determined strength value at each depth."]'::jsonb, 2, 'Conservative in which direction, at which slowness? At the deepest readings the shale correlation is the LESS conservative one.'),
  ('geomech', 'beginner', 'module', 'm04-strength-from-a-log', 9, 'What should you do when the lithology is uncertain?', '["Use the shale correlation, which is safer.", "Run both and quote the range, saying which end each decision was made on.", "Take the average of the two, which removes the bias from choosing the wrong one and halves the resulting uncertainty.", "Use whichever gives the narrower mud window, since that is the conservative choice under any circumstances."]'::jsonb, 1, 'Treating the lower value as conservative is wrong more often than people expect.'),
  ('geomech', 'beginner', 'module', 'm04-strength-from-a-log', 10, 'Why does the engine return a provenance string with every UCS?', '["Because a strength quoted without saying which correlation produced it cannot be audited.", "Because the regulator requires a citation.", "Because the two correlations have different units at the interface, so the string is needed to interpret the number.", "Because the provenance carries the calibration range, which the engine uses to decide whether to return a value at all."]'::jsonb, 0, 'It is a small thing and it is the right behaviour.'),
  ('geomech', 'beginner', 'module', 'm04-strength-from-a-log', 11, 'What is q for salt, and what does that mean?', '["Zero, because salt has no strength at all.", "About three, the same as most sedimentary rocks, because the friction angle of halite is close to thirty degrees.", "Undefined, because salt is not a frictional material and the Mohr-Coulomb criterion does not apply to it.", "One, which means confinement buys nothing and salt cannot sustain a stress difference."]'::jsonb, 3, 'It is why salt flows, and why a salt section has to be drilled at the overburden gradient rather than anywhere in a window.'),
  ('geomech', 'beginner', 'module', 'm04-strength-from-a-log', 12, 'Where does the friction angle appear a second time?', '["In the tensile strength.", "In the axial wall stress, where it corrects the Poisson term for the shear resistance of the rock at the wall.", "In the frictional bounds on the horizontal stresses.", "In the equivalent mud weight conversion, where it accounts for the frictional pressure loss in the annulus."]'::jsonb, 2, 'The engine uses one value in both places, which conflates a fault surface property with an intact rock property.'),
  ('geomech', 'beginner', 'module', 'm04-strength-from-a-log', 13, 'What are the lithology seeds?', '["Measured average properties per rock type.", "Starting values for a screening run on a well with no core and no shear sonic.", "The calibrated results of a large industry database of triaxial tests, indexed by lithology and by burial depth range.", "Default values that the engine substitutes whenever a log value is missing, computed from the surrounding samples."]'::jsonb, 1, 'There is no such thing as the Poisson ratio of sandstone: it varies far more widely than the table''s rows differ.'),
  ('geomech', 'beginner', 'module', 'm04-strength-from-a-log', 14, 'Reading the seed table, what makes shale the difficult rock?', '["The highest Poisson ratio and the lowest friction angle, and both push toward a narrower window.", "The lowest cohesion of the five.", "The lowest Young''s modulus, which means it deforms most under the stress concentration around the hole wall.", "The highest cohesion, which makes it strong when intact and therefore prone to failing suddenly rather than gradually."]'::jsonb, 0, 'A high Poisson ratio gives a high k0 and therefore high horizontal stresses; a low friction angle gives little confinement benefit.'),
  ('geomech', 'beginner', 'module', 'm04-strength-from-a-log', 15, 'When is a seed value dangerous?', '["When it is used for the wrong lithology.", "When it is outside the range the correlation was calibrated over, which the engine detects and warns about automatically.", "When two seeds are used together, since the table''s rows were not derived from the same set of measurements.", "When it survives into a final answer without anybody noticing it was a default."]'::jsonb, 3, 'A collapse gradient quoted to three decimals from a seeded Poisson ratio is claiming a precision it does not have.'),
  ('geomech', 'beginner', 'module', 'm05-reading-the-model-critically', 1, 'What does the quality score check?', '["Stress ordering against the stated faulting regime, and whether any sample is missing.", "Whether the stresses match a leak-off test.", "The agreement between the engine''s output and the published golden file, expressed as a percentage of the samples that match.", "Whether the model''s inputs fall inside the calibration ranges of the correlations that produced them."]'::jsonb, 0, 'Two checks, both internal, both cheap, and both worth reading before any output.'),
  ('geomech', 'beginner', 'module', 'm05-reading-the-model-critically', 2, 'Why are the deductions flat rather than proportional?', '["Because a proportional score is harder to compute.", "Because the number of violations is not known until the whole profile has been evaluated, which happens after the score is set.", "Because the score is a flag rather than a metric: its job is to make somebody look.", "Because a proportional score would be dominated by the sample spacing, which is a modelling choice rather than a data property."]'::jsonb, 2, 'A score falling smoothly with the count would invite treating 91 as acceptable and 89 as not, which is false precision on a diagnostic.'),
  ('geomech', 'beginner', 'module', 'm05-reading-the-model-critically', 3, 'What does this profile score, and why?', '["100, because it is complete and consistent.", "80, because 23 of its 52 samples put SHmax above the overburden.", "65, because it has both an ordering violation and a set of missing samples in the shallowest part of the section.", "80, because four of the samples were clamped to the frictional bounds and the score deducts for clamping."]'::jsonb, 1, 'Nearly half the profile is in a stress state the run says it is not in, and the score exists to make that visible.'),
  ('geomech', 'beginner', 'module', 'm05-reading-the-model-critically', 4, 'Which samples violate the ordering, and which condition?', '["The deepest samples, on pore pressure above Shmin.", "A scattered subset throughout the profile, on a mixture of the three conditions the quality score tests for.", "The samples immediately above and below the pore pressure ramp, where the effective stress changes most rapidly.", "The 23 shallowest, all on the same condition: the overburden below SHmax."]'::jsonb, 3, 'Not SHmax below Shmin, and not pore pressure above Shmin. One condition, in a contiguous block from the top.'),
  ('geomech', 'beginner', 'module', 'm05-reading-the-model-critically', 5, 'What does a horizontal stress above the vertical one mean?', '["The rock is in tension.", "The overburden has been underestimated, which is the only mechanism by which the ordering can be inverted in a real basin.", "The stress state is not normal faulting, whatever the run was told.", "The pore pressure exceeds the minimum horizontal stress, which is the definition of an overpressured seal."]'::jsonb, 2, 'The regime decides which frictional bound applies and how a hole is loaded, so an inconsistency there propagates everywhere.'),
  ('geomech', 'beginner', 'module', 'm05-reading-the-model-critically', 6, 'Is the clamping responsible for the violation?', '["No. Only four of the 23 depths are clamped at all, so 19 got there through the estimate alone.", "Yes. Every violating sample is clamped.", "Partly. The clamp is responsible above 500 m and the estimate is responsible below it, with the two overlapping in between.", "It cannot be determined from the engine''s output, because the clamp count is reported per run rather than per sample."]'::jsonb, 0, 'That is worth checking rather than assuming, and the clamp count is what makes it checkable.'),
  ('geomech', 'beginner', 'module', 'm05-reading-the-model-critically', 7, 'Which term is responsible?', '["The Poisson ratio, which is too high.", "The tectonic strain term, which is fixed while the burial term grows with depth.", "The Biot coefficient, which at a value of one overstates the effect of the pore pressure at shallow depth where it is small.", "The overburden gradient, which at a constant value overstates the vertical stress in the shallowest part of the section."]'::jsonb, 1, 'At 50 m the strain term is twelve times the burial part. At 2600 m it is about a fifth of it.'),
  ('geomech', 'beginner', 'module', 'm05-reading-the-model-critically', 8, 'Where does the violation end, and what sets that depth?', '["At the top of the pore pressure ramp.", "At the deepest clamped sample, because clamping is what produces the violation and it stops where the clamping stops.", "At the depth where the two horizontal stresses become equal, which is the transition between two faulting regimes.", "Between 1150 m and 1200 m, where the burial term has grown enough for the sum to fall below the overburden."]'::jsonb, 3, 'It depends on the strain term''s size, k0 and the overburden gradient. Change any of them and it moves.'),
  ('geomech', 'beginner', 'module', 'm05-reading-the-model-critically', 9, 'What does the engine do about the violation?', '["Refuses to run below the affected depth.", "Switches the faulting regime automatically for the affected samples, then reports which samples were treated differently.", "Reports it through the quality score and computes anyway.", "Substitutes the overburden for SHmax wherever the ordering is broken, which restores consistency at the cost of accuracy."]'::jsonb, 2, 'Defensible: refusing would leave the user with nothing, and computing with a loud warning leaves them with a reason to distrust it.'),
  ('geomech', 'beginner', 'module', 'm05-reading-the-model-critically', 10, 'What is the general modelling lesson from the strain term?', '["A depth-independent addition to a depth-proportional quantity is only safe where the two are comparable.", "Tectonic strain should never be included.", "A model should refuse to extrapolate above its shallowest calibration point, and this engine does exactly that.", "Constant terms should always be expressed as gradients so that they scale correctly with depth throughout the section."]'::jsonb, 0, 'The formulation is standard and fine at reservoir depth. It is being extrapolated to 50 m, where it has no business being.'),
  ('geomech', 'beginner', 'module', 'm05-reading-the-model-critically', 11, 'What does a real study do about the shallow section?', '["Uses a lower Poisson ratio there.", "Calibrates at depth and declines to extrapolate the model above the shallowest calibration point.", "Reduces the tectonic strain linearly to zero at surface, which restores the ordering without changing the deep answers.", "Applies the frictional bounds more tightly at shallow depth, which is the purpose the bounds were introduced to serve."]'::jsonb, 1, 'The shallow section gets drilled on experience and offset data instead, which is what actually happens.'),
  ('geomech', 'beginner', 'module', 'm05-reading-the-model-critically', 12, 'How should a clamped stress be read?', '["As the model''s best estimate of the value.", "As a measurement, since the frictional bound is derived from a physical constraint rather than from an elastic model.", "As an error, since a clamped value indicates that one of the model''s inputs was outside its valid range.", "As the most it could be, with the true value somewhere at or below it."]'::jsonb, 3, 'A clamped value is not the estimate any more. It is the edge of the range the estimate was supposed to lie in.'),
  ('geomech', 'beginner', 'module', 'm05-reading-the-model-critically', 13, 'What is the commonest failure in reading a stress model?', '["Using pascals instead of equivalent mud weight.", "Applying the wrong faulting regime, which is caught immediately by the quality score and therefore rarely survives review.", "A clamp count above zero with no comment anywhere in the report.", "Interpolating the profile onto the trajectory, which introduces an error that compounds along the length of the well."]'::jsonb, 2, 'It is easy to compute and easy not to look at, and it is the difference between a prediction and a boundary.'),
  ('geomech', 'beginner', 'module', 'm05-reading-the-model-critically', 14, 'How should the quality score be used?', '["As the first thing you read, because the warning tells you which part of the profile to distrust.", "As a measure of how accurate the model is.", "As an acceptance criterion, with a threshold below which the run should be repeated with different input parameters.", "As a comparison between runs, since a higher score always indicates a better calibrated and more reliable stress model."]'::jsonb, 0, 'A good score is a necessary condition and nowhere near a sufficient one: a profile can score 100 and be completely wrong.'),
  ('geomech', 'beginner', 'module', 'm05-reading-the-model-critically', 15, 'Which question should be asked of every stress number?', '["Is this in pascals or in equivalent mud weight?", "Is this a measurement, an estimate, or a bound?", "Was it produced by the same version of the engine as the rest of the profile, and if not, which version produced it?", "Does it fall between the pore pressure and the overburden, which is the only physically admissible range for a stress?"]'::jsonb, 1, 'All three get printed in the same font, and a report that does not label them is asking you to treat them the same.'),
  ('geomech', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Reduce the Associate tier to one claim.', '["Rock strength comes from a sonic correlation.", "The two horizontal stresses are estimated from the overburden and the pore pressure using an elastic relationship with a strain term.", "Two of the six numbers are model outputs, and the model tells you when it has stopped believing itself.", "Every pressure in the model can be expressed as an equivalent mud weight by dividing by gravity and the true vertical depth."]'::jsonb, 2, 'The other statements are true and are parts of it. That one is what the tier established.'),
  ('geomech', 'beginner', 'module', 'm06-the-associate-reading', 2, 'Which parameter set does the capstone run?', '["One where nothing matches the published values: a different Poisson ratio, friction angle, modulus, strains, Biot coefficient and azimuth.", "The published set, on a different well.", "The published set with only the Poisson ratio changed, so that the effect of that one parameter can be isolated cleanly.", "A set chosen by the learner, since the capstone grades the method rather than any particular numerical answer."]'::jsonb, 0, 'So no graded value is a number a lesson printed, which is the design rule for every capstone in this series.'),
  ('geomech', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Which two capstone fields need only one input each?', '["The two horizontal stresses at 2000 m.", "k0 from the Poisson ratio, and the frictional limit ratio from the friction angle.", "The two unconfined compressive strengths, since both follow directly from the core plug sonic reading and nothing else.", "The two strain terms, which depend only on the Young''s modulus and the two tectonic strain values supplied."]'::jsonb, 1, 'Both are one line, both feed the two after them, and both have a free directional check against the published values.'),
  ('geomech', 'beginner', 'module', 'm06-the-associate-reading', 4, 'What is the free check on the first two fields?', '["Both must be larger than one.", "Their product must equal the ratio of the two horizontal stresses at any depth, which is a property of the uniaxial estimate.", "They must sum to the frictional bound at 2000 m, divided by the effective vertical stress at that depth.", "Both must come out smaller than the published values, because both input parameters are lower."]'::jsonb, 3, 'If either went the other way, the formula is upside down.'),
  ('geomech', 'beginner', 'module', 'm06-the-associate-reading', 5, 'What has to be checked before reporting the two stress fields?', '["Whether either has been clamped to a frictional bound at that depth.", "Whether the sonic reading is in the right units.", "Whether the pore pressure at 2000 m sits above or below the hydrostatic gradient, since the ramp begins above that depth.", "Whether the overburden gradient at 2000 m matches the constant value the profile carries at every other depth."]'::jsonb, 0, 'If a stress is clamped, the clamped value is the answer rather than the raw estimate, and working out which is part of the task.'),
  ('geomech', 'beginner', 'module', 'm06-the-associate-reading', 6, 'What is the trap in the two strength fields?', '["The two correlations give the same answer.", "The core plug reading is one of the profile''s own sonic samples, so the published UCS column already contains the answer.", "The McNally correlation takes slowness in microseconds per foot, and the reading is given per metre.", "Both correlations return a value in megapascals, and the capstone asks for pascals, which is a factor of a thousand."]'::jsonb, 2, 'Getting that conversion wrong changes the answer by orders of magnitude rather than by percent.'),
  ('geomech', 'beginner', 'module', 'm06-the-associate-reading', 7, 'Why is the core plug reading not one of the profile''s samples?', '["Because core plugs are measured differently.", "So that neither strength field can be read out of the published UCS column.", "Because the profile''s sonic samples are spaced at 50 m and the capstone depth falls between two of them, requiring interpolation.", "Because the published UCS column was computed with McNally, so the Horsrud value at the same reading would be new anyway."]'::jsonb, 1, 'The published column was computed with one correlation at the profile''s own samples, and the capstone uses neither.'),
  ('geomech', 'beginner', 'module', 'm06-the-associate-reading', 8, 'What does the tier hand to the Professional tier?', '["A completed mud weight window.", "The quality score and clamp count, which the stability calculation uses to decide how much confidence to place in its inputs.", "The trajectory of both wells, together with the interpolation needed to place the profile onto them.", "Four stresses and a strength at every depth."]'::jsonb, 3, 'That is exactly what the wall stress calculation consumes, and nothing new is estimated in the next tier.'),
  ('geomech', 'beginner', 'module', 'm06-the-associate-reading', 9, 'What did this tier take entirely on trust?', '["The overburden and the pore pressure, both of which arrive from upstream.", "The friction angle and the Poisson ratio.", "The sonic log, which is the only direct measurement in the six and is therefore the one input that needs no justification.", "The frictional bounds, which are a physical constraint rather than a model output and so cannot be questioned."]'::jsonb, 0, 'The engine deliberately does not compute the pore pressure, so a geomechanics answer cannot contain a circular argument about it.'),
  ('geomech', 'beginner', 'module', 'm06-the-associate-reading', 10, 'Which habit does the tier name about equivalent mud weight?', '["Convert as early as possible.", "Use equivalent mud weight throughout, since it is the unit the decision is made in and the conversion is trivial either way.", "Convert only at the end, and always with the depth attached.", "Quote both units for every number, so that a reader can check the conversion without needing to know the depth."]'::jsonb, 2, 'The physics is in pressures and the decision is in mud weights, and the conversion is where the two meet.'),
  ('geomech', 'beginner', 'module', 'm06-the-associate-reading', 11, 'What is coming in the Professional tier?', '["A second stress model for comparison.", "A hole drilled in this rock, with the far-field stresses rotated into the borehole frame.", "The mud weight window walked along a whole trajectory, with the tightest point identified and the two lower bounds separated.", "A calibration of the model against caliper and loss data from a set of offset wells in the same field."]'::jsonb, 1, 'Two failure criteria then turn the wall stresses into a lower and an upper bound on the mud weight at one depth.'),
  ('geomech', 'beginner', 'module', 'm06-the-associate-reading', 12, 'Which single case in the course can a third party settle on paper?', '["A vertical well in the published stress fixture, whose collapse and fracture pressures both have closed forms.", "The stress profile at 2000 m.", "The unconfined compressive strength at any sonic reading, since both correlations are one-line formulas that need no solver.", "The frictional bounds at any depth, which follow directly from the effective vertical stress and the friction angle."]'::jsonb, 0, 'The engine reproduces both exactly rather than nearly, which is the strongest check in the whole course.'),
  ('geomech', 'beginner', 'module', 'm06-the-associate-reading', 13, 'What is the status of the two horizontal stresses in any output?', '["Measurements, once a leak-off test exists.", "Bounds rather than estimates, since the frictional limits are applied to every sample before the result is returned.", "Interpolated values, since the profile is sampled at 50 m and the true stress varies continuously with depth.", "Model outputs carrying the uncertainty of every parameter that went into them."]'::jsonb, 3, 'A leak-off test bounds Shmin at a handful of depths. SHmax is essentially never measured directly at all.'),
  ('geomech', 'beginner', 'module', 'm06-the-associate-reading', 14, 'Which of the six inputs would you spend money on first, on this evidence?', '["The overburden, since everything derives from it.", "The pore pressure, because it is the only input that appears in both the lower bound and the effective stress calculation.", "Whichever the sensitivity study says moves the answer most, which has to be computed rather than assumed.", "The unconfined compressive strength, because it comes from a correlation rather than a measurement on this well."]'::jsonb, 2, 'The Expert tier does exactly that sweep, and its answer is not the one the conventional wish list would give.'),
  ('geomech', 'beginner', 'module', 'm06-the-associate-reading', 15, 'What is the honest label for a screening geomechanics answer?', '["A validated engineering calculation.", "An estimate to be calibrated as the well is drilled, not a prediction to be relied on.", "A bound on the achievable mud weight, since the frictional limits ensure the answer cannot be outside the physically possible range.", "A measurement of the stress state, since every input traces back to a log run on the well in question."]'::jsonb, 1, 'That is why the first section of a well is drilled most conservatively, and why the calibration loop exists at all.'),
  ('geomech', 'beginner', 'final', null, 1, 'A colleague asks what you actually need to build a mechanical earth model. What do you tell them?', '["Three stresses, a pore pressure, a sonic reading and a strength, at every depth.", "A density log and a Poisson ratio.", "A full triaxial test programme on core, supported by a shear sonic log and an image log over the whole interval of interest.", "A calibrated relationship between drilling parameters and formation strength, built from the offset wells in the field."]'::jsonb, 0, 'Six numbers, no seventh, and everything downstream is a function of them.'),
  ('geomech', 'beginner', 'final', null, 2, 'Two of the six are never measured on an ordinary well. Which two?', '["The overburden and the pore pressure.", "The unconfined compressive strength and the friction angle, both of which require core that is rarely cut on a development well.", "SHmax and Shmin.", "The sonic slowness and the bulk density, which are the two logs most often dropped from a cost-constrained programme."]'::jsonb, 2, 'Shmin is bounded at a handful of depths by a leak-off test; SHmax essentially never directly.'),
  ('geomech', 'beginner', 'final', null, 3, 'A report quotes a fracture gradient of 2200 kg per cubic metre with no depth beside it. What is wrong?', '["Nothing. It is a gradient, so it is depth-independent.", "An equivalent mud weight without a depth cannot be converted back into a pressure.", "The units are wrong: a gradient should be expressed in pascals per metre rather than as an equivalent fluid density.", "A fracture gradient should always be quoted at the shoe, so the missing item is the casing size rather than the depth."]'::jsonb, 1, 'It is the commonest error in reading a geomechanics report, and it takes one clause to avoid.'),
  ('geomech', 'beginner', 'final', null, 4, 'Why does the engine work in pascals and convert only at the end?', '["Because pascals are the SI unit.", "Because equivalent mud weight cannot represent a negative value, and effective stresses are sometimes negative in the model.", "Because the failure criteria are dimensionless, so they can only be evaluated once the depth has been divided out.", "Because the physics is in pressures, and converting partway through adds a place to make a mistake."]'::jsonb, 3, 'The decision is in mud weights and the calculation is in pressures.'),
  ('geomech', 'beginner', 'final', null, 5, 'A well planner has a choice of approach azimuth to a target. What can this model tell them?', '["Nothing. The window is a property of depth alone.", "That the shallower approach will always be the more stable one, because the rock is stronger nearer the surface of the section.", "That the window depends on which way the hole points, sometimes by a third of it.", "Which azimuth gives the shortest measured depth, which is the main driver of drilling cost and therefore of the decision."]'::jsonb, 2, 'That is the second of the three decisions the model is for, and often the more valuable one.'),
  ('geomech', 'beginner', 'final', null, 6, 'You are handed a vertical stress curve with no explanation. How was it built?', '["Integrating a bulk density log from surface.", "A correlation with the sonic slowness.", "The sum of the two horizontal stresses divided by twice the ratio of horizontal to vertical stress in the faulting regime.", "A leak-off test at each shoe, with the values between shoes filled in by a linear trend against true vertical depth."]'::jsonb, 0, 'Arithmetic on a measurement, with the shallow section as the main uncertainty.'),
  ('geomech', 'beginner', 'final', null, 7, 'This profile assumes a constant overburden gradient. Where is that assumption worst?', '["At total depth, where errors accumulate.", "Near surface, where the sediment has not compacted.", "Across the pore pressure ramp, where the effective stress changes fastest and the assumption is least able to keep up.", "It is equally wrong everywhere, because a constant gradient cannot represent a compacting sediment column at any depth."]'::jsonb, 1, 'By 2000 m a real gradient has flattened out and a constant value is close.'),
  ('geomech', 'beginner', 'final', null, 8, 'Why does a shallow overburden error propagate so far here?', '["Because the sonic log is unreliable there too.", "Because the shallow section carries the casing shoe, so its fracture gradient governs the whole of the section below it.", "Because the pore pressure model uses the overburden as a reference, so an error in one duplicates itself in the other.", "Because the horizontal stresses are computed from the overburden."]'::jsonb, 3, 'Too large an overburden at shallow depth gives horizontal stresses that are too large there.'),
  ('geomech', 'beginner', 'final', null, 9, 'Why does the geomechanics engine refuse to compute the pore pressure itself?', '["Because pore pressure needs a different unit system.", "Because the pore pressure model needs a resistivity log, which the geomechanics module does not accept as an input.", "So a geomechanics answer can never contain a circular pore pressure argument.", "Because the pore pressure is measured directly by a formation tester and therefore does not need to be computed at all."]'::jsonb, 2, 'A module that both estimates and consumes the same quantity can hide the circularity from its own user.'),
  ('geomech', 'beginner', 'final', null, 10, 'The pore pressure in this profile is flat and then rises. What does the flat part mean?', '["The fluid escaped upward as fast as the sediment compacted, leaving just the weight of the water above.", "The formation is impermeable.", "The pore pressure was measured at only one depth and held constant above it, which is a common modelling shortcut.", "The pore fluid is gas rather than brine, which gives a much lower gradient over the interval concerned."]'::jsonb, 0, 'That is the definition of a normally pressured section.'),
  ('geomech', 'beginner', 'final', null, 11, 'And what does the rising part mean for the effective vertical stress?', '["It grows faster, since both terms rise.", "It stops growing as fast, because the pore pressure is eating the increase.", "It becomes negative, which is why an overpressured section always needs a heavier mud than a normally pressured one.", "It is unaffected, because the effective stress is defined against the hydrostatic gradient rather than the actual pore pressure."]'::jsonb, 1, 'Deeper rock in an overpressured section can be weaker than shallower rock above it.'),
  ('geomech', 'beginner', 'final', null, 12, 'Rock strength depends on effective stress rather than total. Justify that.', '["Because it is small compared with the stresses.", "Because the failure criteria are written in total stresses, so the pore pressure never enters them in the first place.", "Because the pore fluid carries no shear, so it cannot contribute to the shear stress that drives Mohr-Coulomb failure.", "It presses equally from every side, so it cancels out of the stress differences that break rock."]'::jsonb, 3, 'What breaks a rock is the difference between the loads on different faces, and the pore pressure subtracts from all of them.'),
  ('geomech', 'beginner', 'final', null, 13, 'What does a Biot coefficient below one represent?', '["That the rock is partly saturated.", "That some of the pore space is unconnected, so the measured pore pressure does not act throughout the rock volume.", "That the grains themselves are compressible, so the pore pressure is not fully effective.", "That the rock is anisotropic, so the effective stress law has to be written separately in each principal direction."]'::jsonb, 2, 'Closer to one for a soft high-porosity rock, and setting it to one is the conservative default.'),
  ('geomech', 'beginner', 'final', null, 14, 'State the picture behind the uniaxial horizontal stress estimate.', '["Rock buried under more rock, free to compress vertically and prevented from expanding sideways.", "Rock loaded equally in all three directions.", "Rock at the frictional limit on existing faults, with the stress state sitting exactly on the Andersonian bound everywhere.", "Rock deforming plastically under its own weight, so that all three stresses converge on the overburden value with depth."]'::jsonb, 0, 'It is reasonable for a thick flat-lying sequence loaded by burial and poor near a fault or a salt body.'),
  ('geomech', 'beginner', 'final', null, 15, 'Give k0 in terms of the Poisson ratio, and say why it is always below one.', '["One minus nu over nu, and it is below one at low nu.", "nu over one minus nu, and it is below one because burial alone gives less horizontal effective stress than vertical.", "Twice nu over one plus nu, which stays below one for any physically admissible value of the Poisson ratio in rock.", "The ratio of the shear modulus to the bulk modulus, which cannot exceed one for a material with positive elastic constants."]'::jsonb, 1, 'It approaches one as nu approaches a half, which is an incompressible material such as salt.'),
  ('geomech', 'beginner', 'final', null, 16, 'A shale and a sandstone are given seed Poisson ratios of 0.35 and 0.20. What follows for k0?', '["The two k0 values differ by about 15 percent.", "The shale''s is lower, because a higher Poisson ratio means the rock resists lateral expansion more effectively under load.", "They are the same, because k0 depends on the effective vertical stress rather than on the elastic properties of the rock.", "The shale''s k0 is more than twice the sandstone''s."]'::jsonb, 3, '0.20 gives 0.25 and 0.35 gives about 0.538, and the relationship accelerates as nu rises.'),
  ('geomech', 'beginner', 'final', null, 17, 'The tectonic strain term has one property that causes all the trouble. Which?', '["It depends on the pore pressure.", "It is applied only to the maximum horizontal stress, which is why the two stresses diverge with depth in this model.", "It does not depend on depth.", "It scales with the Young''s modulus, which varies by a factor of four across the lithology seeds this course carries."]'::jsonb, 2, 'The same pressure is added at 50 m as at 2600 m, which is a large fraction of one and a small fraction of the other.'),
  ('geomech', 'beginner', 'final', null, 18, 'Shmin and SHmax come out of one formula. What is the only difference?', '["The order of the two tectonic strains, so the whole difference between the stresses is tectonic.", "The Poisson ratio used in each of them.", "The frictional bound applied, since the active limit constrains the smaller and the passive limit constrains the larger.", "The pore pressure, which is added back for the total minimum stress and left out for the total maximum one."]'::jsonb, 0, 'Burial has no horizontal direction to it, so it cannot distinguish one horizontal stress from the other.'),
  ('geomech', 'beginner', 'final', null, 19, 'In this profile the difference between the two horizontal stresses does what with depth?', '["Grows in proportion to the effective stress.", "Stays exactly the same in pressure, while shrinking in equivalent mud weight terms.", "Falls to zero at the depth where the two curves cross, below which the ordering of the two stresses is reversed.", "Varies with lithology, being largest in the stiff intervals and smallest in the soft ones through the section."]'::jsonb, 1, 'A constant strain difference gives a constant stress difference, and the gradient plot just divides it by a growing depth.'),
  ('geomech', 'beginner', 'final', null, 20, 'What are the frictional bounds, and what kind of statement are they?', '["Estimates of the stress from fault geometry.", "Calibration constraints derived from leak-off tests, which bound the minimum horizontal stress at each casing shoe from above.", "Numerical limits imposed to keep the solver stable, with no physical meaning beyond preventing an unbounded result.", "Limits from friction on existing faults, and they are BOUNDS rather than estimates."]'::jsonb, 3, 'The engine''s header notes that a legacy version mixed the two, which is claiming to know a stress when you know a range.'),
  ('geomech', 'beginner', 'final', null, 21, 'A fault surface with thirty degrees of friction bounds the stress ratio at what value?', '["About 0.577, the tangent of the angle.", "About 1.732, the square root of three, which is the value most often quoted in the rock mechanics literature.", "Exactly three.", "It depends on the effective vertical stress as well as the angle, so no single value can be given for it."]'::jsonb, 2, 'One plus the sine over one minus the sine, and the value of three is the one most often quoted.'),
  ('geomech', 'beginner', 'final', null, 22, 'You see two horizontal stresses reported as exactly equal at a depth. What should you suspect?', '["That both were clamped to the same frictional bound.", "That the rock is isotropic there.", "That the tectonic strains were entered as equal, which makes the two formulas identical and the two answers the same.", "That the sample is missing and the engine has substituted the same default value for both of the two stresses."]'::jsonb, 0, 'Two stresses agreeing exactly is almost never physical. It is the signature of a clamp.'),
  ('geomech', 'beginner', 'final', null, 23, 'Define unconfined compressive strength, and say what the word unconfined is doing.', '["The strength of the rock at reservoir conditions.", "The load per unit area at which a plug fails with nothing holding its sides in, and confinement raises it a great deal.", "The largest stress difference the rock can sustain, measured at the confining pressure appropriate to the depth in question.", "The pressure at which the rock begins to deform permanently rather than elastically under a purely hydrostatic load."]'::jsonb, 1, 'It is the intercept of the failure line, and the friction angle supplies the slope.'),
  ('geomech', 'beginner', 'final', null, 24, 'Which correlation is for shale, and what functional form does it have?', '["McNally, an exponential in the slowness.", "Both are for shale, since the two were calibrated on different shale datasets and differ only in the region they were fitted over.", "Horsrud, an exponential in the slowness expressed in microseconds per foot rather than per metre.", "Horsrud, a power law in the compressional velocity."]'::jsonb, 3, '0.77 times the velocity in km per second raised to the power 3.2, from Horsrud 2001 on North Sea shales.'),
  ('geomech', 'beginner', 'final', null, 25, 'How many times do the two strength correlations cross, and where relative to this profile?', '["Once, near the middle of the range.", "Never. A power law and an exponential are monotone functions of the same argument and therefore cannot intersect at all.", "Twice, and both crossings are inside its sonic range.", "Three times, since the exponential overtakes the power law and falls behind it more than once over the range."]'::jsonb, 2, 'A power law and an exponential meet at most twice, and this profile spans all three regions between and outside them.'),
  ('geomech', 'beginner', 'final', null, 26, 'Given that the two curves meet twice, which common piece of advice becomes untenable?', '["Any claim that one of the two correlations is the conservative choice.", "The usefulness of both correlations.", "The ability to estimate strength from a sonic log at all, since the answer depends on an unmeasurable lithology assignment.", "The Mohr-Coulomb criterion, which assumes a single well-determined strength at each point in the section."]'::jsonb, 0, 'Conservative in which direction, at which slowness? At the deepest readings the shale correlation is the less conservative one.'),
  ('geomech', 'beginner', 'final', null, 27, 'Halite has zero friction. Trace that through to how a salt section gets drilled.', '["Zero, because salt has no shear strength.", "One, so confinement buys nothing and salt cannot sustain a stress difference at all.", "About three, the same as most sedimentary rocks, since halite has a friction angle close to thirty degrees in triaxial tests.", "Undefined, because the Mohr-Coulomb criterion does not apply to a material that deforms by creep rather than by fracture."]'::jsonb, 1, 'It is why salt flows and why a salt section is drilled at the overburden gradient rather than inside a window.'),
  ('geomech', 'beginner', 'final', null, 28, 'The friction angle appears in two places in this model. Where?', '["In the strength correlation and in the tensile strength.", "In the Mohr-Coulomb criterion and in the Biot coefficient, both of which describe how the grain framework carries load.", "In the collapse criterion and in the fracture criterion, which is why lowering it narrows the window from both directions.", "At the wall as the slope of the failure line, and in the frictional bounds on the horizontal stresses."]'::jsonb, 3, 'The engine uses one value for both, which conflates a fault surface property with an intact rock one.'),
  ('geomech', 'beginner', 'final', null, 29, 'A report quotes a collapse gradient computed from a seeded Poisson ratio, to three decimals. What is wrong?', '["Nothing, if the seed came from the right lithology.", "The Poisson ratio should never be seeded, so the whole calculation is invalid and the result should not be quoted at all.", "The precision claims more than the model can support.", "Collapse gradients should be quoted in pascals rather than as equivalent mud weights, which is where the precision was lost."]'::jsonb, 2, 'The sensitivity module shows the Poisson ratio alone moves the answer by hundreds of kilograms per cubic metre.'),
  ('geomech', 'beginner', 'final', null, 30, 'Before reading any output, one diagnostic is worth a glance. What does it test?', '["Stress ordering against the stated regime, and whether any sample is missing.", "Agreement with the golden file and the clamp count.", "Whether the inputs fall inside the calibration ranges of the correlations, and whether the profile covers the whole trajectory.", "The relative error against an independent implementation, and the number of bisection steps needed for convergence."]'::jsonb, 0, 'Two internal checks, both cheap, and both worth reading before any output.'),
  ('geomech', 'beginner', 'final', null, 31, 'This profile scores 80. What is the warning, and how much of the profile does it cover?', '["Four samples were clamped to the frictional bounds.", "Twenty-three of 52 samples put SHmax above the overburden, which is 44 percent of it.", "The pore pressure exceeds the minimum horizontal stress below the ramp, which affects the deepest twenty samples of the profile.", "The sonic log is missing over the shallowest interval, so the strength column could not be computed for those depths."]'::jsonb, 1, 'Not a small anomaly at the edge of the data. Nearly half of it.'),
  ('geomech', 'beginner', 'final', null, 32, 'Somebody blames the frictional bounds for the shallow ordering breach. Are they right?', '["Yes, all 23 are clamped samples.", "Partly, with clamping responsible above about 500 m and the estimate responsible below it over the rest of the interval.", "It cannot be told from the output, because the engine reports the clamp count per run rather than identifying which samples.", "No. Only four of the 23 depths are clamped, so 19 got there through the estimate alone."]'::jsonb, 3, 'The clamp count is what makes that checkable rather than a matter of assumption.'),
  ('geomech', 'beginner', 'final', null, 33, 'Which term is responsible, and how do you know?', '["The Poisson ratio, because it is too high.", "The overburden gradient, because a constant value overstates the vertical stress in the shallowest part of the section.", "The tectonic strain term, because it is fixed while the burial term grows with depth.", "The Biot coefficient, because at one it removes too much of the pore pressure from the effective vertical stress."]'::jsonb, 2, 'At 50 m the strain term is twelve times the burial part, and at 2600 m about a fifth of it.'),
  ('geomech', 'beginner', 'final', null, 34, 'Generalise beyond geomechanics: what does the shallow breach warn about in any model?', '["A depth-independent addition to a depth-proportional quantity is only safe where the two are comparable.", "Tectonic strain should be left out of the model.", "A stress model should refuse to run above the shallowest depth at which it was calibrated, which this engine already does.", "Constant terms should be re-expressed as gradients, so that they scale correctly through the whole of the section."]'::jsonb, 0, 'The formulation is standard and fine at reservoir depth. It is being extrapolated to 50 m.'),
  ('geomech', 'beginner', 'final', null, 35, 'A stress sits exactly on a computed bound. What does that value actually tell you?', '["As the model''s best estimate of the value.", "As the most it could be, with the true value at or below it.", "As a physical measurement, since the frictional bound is a constraint from fault mechanics rather than an elastic model output.", "As an error condition, since a clamp means one of the inputs was outside the range the engine can handle correctly."]'::jsonb, 1, 'It is the edge of the range the estimate was supposed to lie inside, not the estimate.'),
  ('geomech', 'beginner', 'final', null, 36, 'What is the single question to ask of every stress number in a report?', '["Is it in pascals or equivalent mud weight?", "Was it produced by the same engine version as the rest, since a mixed report can contain values computed under different conventions?", "Does it lie between the pore pressure and the overburden, which is the only physically admissible range for a stress?", "Is it a measurement, an estimate, or a bound?"]'::jsonb, 3, 'All three get printed in the same font, and the three carry completely different weight.'),
  ('geomech', 'beginner', 'final', null, 37, 'The Associate capstone changes eight parameters at once. Why?', '["To make the arithmetic harder.", "To demonstrate the sensitivity of the model to its inputs, which is the subject of the Expert tier''s third module.", "So that no graded value is a number a lesson printed.", "Because the published parameter set produces clamped stresses at the capstone depth, which would make the answer ambiguous."]'::jsonb, 2, 'It is the design rule for every capstone in this series, applied deliberately.'),
  ('geomech', 'beginner', 'final', null, 38, 'Which two capstone fields need one input each, and what is the free check on them?', '["k0 from the Poisson ratio and q from the friction angle, and both must come out smaller than the published values.", "The two stresses, checked against the frictional bounds.", "The two strengths, checked against each other using the crossing points that the strength module established for the correlations.", "The two strain terms, checked by confirming that their difference equals the difference between the two horizontal stresses."]'::jsonb, 0, 'Both input parameters are lower than the published ones, so both outputs must be lower too.'),
  ('geomech', 'beginner', 'final', null, 39, 'You have an estimate for Shmin at the graded depth. What stands between it and your answer?', '["Whether the sonic reading is in the right unit.", "Whether it was clamped to a frictional bound at that depth.", "Whether the overburden at that depth matches the constant gradient the profile carries at every other sample in the section.", "Whether the pore pressure at that depth falls on the hydrostatic part of the profile or on the ramp below it."]'::jsonb, 1, 'If it is clamped, the clamped value is the answer, and working out which is part of the task.'),
  ('geomech', 'beginner', 'final', null, 40, 'A learner finishes this tier. What are they carrying into the wall stress work?', '["A completed mud weight window per section.", "The quality score and the clamp count, which the stability calculation uses to weight its confidence in the inputs.", "The two well trajectories, together with the interpolation scheme needed to place the profile onto them.", "Four stresses and a strength at every depth."]'::jsonb, 3, 'That is exactly what the wall stress calculation consumes, and nothing new is estimated downstream of it.'),
  ('geomech', 'beginner', 'final', null, 41, 'The Associate tier takes two of its six inputs entirely on trust. Which, and from where?', '["The two horizontal stresses, from a leak-off test.", "The sonic slowness and the strength, both of which arrive from the log analyst rather than from the geomechanics workflow.", "The overburden from a density log integral, and the pore pressure from the pore pressure course.", "The friction angle and the Poisson ratio, both of which come from the lithology seed table rather than from measurements."]'::jsonb, 2, 'Neither can be checked from inside this course, and an error in either propagates everywhere.'),
  ('geomech', 'beginner', 'final', null, 42, 'If a colleague read only one sentence about this tier, what should it say?', '["Two of the six numbers are model outputs, and the model tells you when it has stopped believing itself.", "Rock strength comes from a sonic correlation.", "The horizontal stresses follow from the overburden and the pore pressure through an elastic relationship with a tectonic term.", "Every pressure can be converted to an equivalent mud weight by dividing by gravity and the true vertical depth."]'::jsonb, 0, 'The others are true and are parts of it. That one is what the tier established.');
